var config = {
  'window': page.variables.window,
  'replay': page.variables.replay,
  'solver': {
    'relativeCost': page.variables['solver.relativeCost'],
    'absoluteCost': page.variables['solver.absoluteCost'],
    'maxIterations': page.variables['solver.maxIterations'],
    'maxEvaluations': page.variables['solver.maxEvaluations']
  },
  'cams': {}
}

Object.keys(page.variables).forEach(key => {
  if (key.includes('cams')) {
    var cam = key.split(".")[1]

    config.cams[cam] = {
      "axes": {
        "x": {
          "weight": page.variables['cams.' + cam + '.x.weight']
        },
        "z": {
          "weight": page.variables['cams.' + cam + '.z.weight']
        }
      }
    }
  }
})

actions.setPageVariable('config', config)

var config = {
  'initialCurrent': page.variables.initialCurrent,
  'beamLifeTime': page.variables.beamLifeTime,
  'noise': page.variables.noise
}

actions.setPageVariable('config', config)

let config = queries.GetSimConfig.data

actions.setPageVariable('initialCurrent', config.initialCurrent)
actions.setPageVariable('beamLifeTime', config.beamLifeTime)
actions.setPageVariable('noise', config.noise)

components.initialCurrent.setText(config.initialCurrent)
components.beamLifeTime.setText(config.beamLifeTime)

if (config.noise == 0) {
  components.noise.setText(String(config.noise))
} else {
  components.noise.setText(config.noise)
}

clearInterval(page.variables.interval)

actions.setPageVariable('interval', setInterval(async () => {
  if (!queries.up.isLoading && !queries.Down.isLoading && !queries.GetConfig.isLoading && !queries.putConfig.isLoading) {
    await queries.GetState.run()
  }

  if (!queries.upSim.isLoading && !queries.DownSim.isLoading && !queries.GetSimConfig.isLoading && !queries.putSimConfig.isLoading) {
    await queries.GetSimState.run()
  }
}, 5000))
